'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {transferRetirementArgs,validateTransferRetirement,readTransferStatus,validateTransferReview,validatePendingTransfer,validateTransferResult,transferSaveArgs,transferAmountMinor,type TransferScope,type TransferReview,type PendingTransfer} from '@/lib/billing-transfer';
import {billingDollars} from './billing-accounts';
type Props=TransferScope&{onBusyChange?:(busy:boolean)=>void;onPendingChange?:(pending:boolean)=>void;actor:string;onSaved:()=>void};
export function BillingTransfer(props:Props){return <Transfer key={[props.actor,props.tenant,props.property,props.account,props.reservation].join('/')} {...props}/>}
function Transfer(props:Props){
 const key=['irp-charge-transfer',props.actor,props.tenant,props.property,props.account,props.reservation].join('/');
 const [initial]=useState(()=>{try{const raw=sessionStorage.getItem(key),cancellation=sessionStorage.getItem(key+'/retirement');if(!raw&&!cancellation)return {pending:null,error:''};const value:unknown=raw?JSON.parse(raw):JSON.parse(cancellation!).pending;validatePendingTransfer(value,props);return {pending:value,error:''}}catch{return {pending:null,error:'Saved transfer could not be read. Resolve browser storage before continuing.'}}});
 const [pending,setPending]=useState<PendingTransfer|null>(initial.pending),[review,setReview]=useState<TransferReview|null>(null),[proposal,setProposal]=useState<PendingTransfer|null>(null),[source,setSource]=useState(''),[amount,setAmount]=useState(''),[reason,setReason]=useState(''),[error,setError]=useState(initial.error),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[revision,setRevision]=useState(0);
 const retirementKey=key+'/retirement';
 const [retirementInitial]=useState(()=>{try{const raw=sessionStorage.getItem(retirementKey);if(!raw)return {reason:'',error:''};const value=JSON.parse(raw);if(!initial.pending||!value||!['reason,request','pending,reason,request'].includes(Object.keys(value).sort().join(','))||value.request!==initial.pending.request)throw Error();if(value.pending){validatePendingTransfer(value.pending,props);if(JSON.stringify(transferSaveArgs(value.pending))!==JSON.stringify(transferSaveArgs(initial.pending)))throw Error()}transferRetirementArgs(initial.pending,value.reason);return {reason:value.reason as string,error:''}}catch{return {reason:'',error:'Saved cancellation could not be read. Keep this transfer request and restore browser storage.'}}});
 const [retirementReason,setRetirementReason]=useState(retirementInitial.reason),[retirementSent,setRetirementSent]=useState(!!retirementInitial.reason);
 const alive=useRef(true),lock=useRef(false);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 useEffect(()=>{let current=true;setReview(null);if(initial.error||retirementInitial.error||pending)return;void hotelRpc<unknown>('billing_route_review',{p_tenant:props.tenant,p_property:props.property,p_account:props.account,p_reservation:props.reservation}).then(value=>{validateTransferReview(value,props);if(current)setReview(value)}).catch(()=>{if(current)setError('Available charges could not be verified. Refresh to try again.')});return()=>{current=false}},[props.tenant,props.property,props.account,props.reservation,revision,pending,initial.error,retirementInitial.error]);
 function prepare(){try{if(!review)throw Error();const line=review.sources.lines.find(line=>line.source_key===source);if(!line)throw Error('Select a charge.');const value:PendingTransfer={version:1,actor:props.actor,request:crypto.randomUUID(),review,source,amount:transferAmountMinor(amount,line.routing_available_minor),reason:reason.trim()};validatePendingTransfer(value,props);setProposal(value);setError('')}catch(e){setError(e instanceof Error?e.message:'Review could not be prepared.')}}
 function verifySaved(value:PendingTransfer,optional=false){
  const raw=sessionStorage.getItem(key),retirement=sessionStorage.getItem(retirementKey);
  if(!raw&&!retirement&&optional)return;
  if(retirement){const marker=JSON.parse(retirement);if(marker.request!==value.request)throw Error('Cancellation identity changed');if(marker.pending){validatePendingTransfer(marker.pending,props);if(JSON.stringify(transferSaveArgs(marker.pending))!==JSON.stringify(transferSaveArgs(value)))throw Error('Cancellation details changed');}}
  const current=raw?JSON.parse(raw):retirement?JSON.parse(retirement).pending:null;
  validatePendingTransfer(current,props);
  if(current.request!==value.request||JSON.stringify(transferSaveArgs(current))!==JSON.stringify(transferSaveArgs(value)))throw Error('Transfer recovery identity changed');
 }
 function clearSaved(value:PendingTransfer){
  verifySaved(value);
  const raw=sessionStorage.getItem(retirementKey);
  if(raw){const marker=JSON.parse(raw);if(!marker||marker.request!==value.request)throw Error('Cancellation identity changed');transferRetirementArgs(value,marker.reason);sessionStorage.setItem(retirementKey,JSON.stringify({request:value.request,reason:marker.reason,pending:value}))}
  sessionStorage.removeItem(key);
  if(raw)sessionStorage.removeItem(retirementKey);
 }
 async function save(){if(lock.current||initial.error||retirementSent||retirementInitial.error)return;const value=pending??proposal;if(!value)return;lock.current=true;setBusy(true);setError('');let sent=false;try{validatePendingTransfer(value,props);verifySaved(value,true);sessionStorage.setItem(key,JSON.stringify(value));setPending(value);sent=true;const result=await hotelRpc<unknown>('create_billing_route',transferSaveArgs(value));validateTransferResult(result,value);if(!alive.current)return;clearSaved(value);if(alive.current){setPending(null);setProposal(null);setSource('');setAmount('');setReason('');setNotice(result.reversed?'This saved transfer was subsequently reversed.':'Charge transferred. No payment was collected.');setRevision(n=>n+1);props.onSaved()}}catch{if(alive.current)setError(sent?'Transfer could not be confirmed. Any saved request is retained; retry it without changing the amount or destination.':'Browser storage could not retain this transfer. No new transfer request was sent.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function checkStatus(){if(lock.current||!pending||initial.error)return;lock.current=true;setBusy(true);setError('');try{const value=await hotelRpc<unknown>('billing_route_status',{p_tenant:props.tenant,p_property:props.property,p_request:pending.request});const result=readTransferStatus(value,pending);if(!alive.current)return;if(!result){setNotice('No saved transfer was found yet. Keep this request and retry; it may still be processing.');return}clearSaved(pending);setRetirementSent(false);setRetirementReason('');setPending(null);setProposal(null);setSource('');setAmount('');setReason('');setNotice(result.reversed?'The saved transfer was subsequently reversed.':'Saved transfer confirmed. No new transfer was sent.');setRevision(n=>n+1);props.onSaved()}catch{if(alive.current)setError('Transfer status could not be verified. The saved request is retained.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function retire(){if(lock.current||!pending||initial.error||retirementInitial.error)return;lock.current=true;setBusy(true);setError('');try{verifySaved(pending);const reason=retirementReason.trim();const args=transferRetirementArgs(pending,reason);sessionStorage.setItem(retirementKey,JSON.stringify({request:pending.request,reason,pending}));setRetirementReason(reason);setRetirementSent(true);const result=await hotelRpc<unknown>('retire_billing_route',args);validateTransferRetirement(result,pending,reason);if(!alive.current)return;clearSaved(pending);setPending(null);setProposal(null);setRetirementSent(false);setRetirementReason('');setNotice('Unsaved transfer cancelled. Delayed copies of this request cannot save.');setRevision(n=>n+1)}catch{if(alive.current)setError('Cancellation could not be confirmed. Keep the saved request; retry cancellation or check whether the transfer already saved.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 useEffect(()=>{props.onBusyChange?.(busy);return()=>props.onBusyChange?.(false)},[busy,props.onBusyChange]);
 useEffect(()=>{props.onPendingChange?.(!!pending||!!initial.error||!!retirementInitial.error)},[pending,initial.error,retirementInitial.error,props.onPendingChange]);
 const selected=pending??proposal;
 return <section className="card" aria-label="Transfer guest charge"><h3>Transfer guest charge</h3>{retirementInitial.error&&<p role="alert">{retirementInitial.error}</p>}{error&&<p role="alert">{error}</p>}{notice&&<p role="status">{notice}</p>}
 {selected?<><p>To: <strong>{selected.review.account_name}</strong></p><p>Charge: {selected.review.sources.lines.find(line=>line.source_key===selected.source)?.description}</p><p>Amount: {billingDollars(selected.amount)}</p><p>Reason: {selected.reason}</p><p>This moves the charge to the billing account. It does not collect a payment.</p><button className="primary" disabled={busy||!!initial.error||retirementSent||!!retirementInitial.error} onClick={()=>void save()}>{busy?'Saving…':pending?'Retry saved transfer':'Confirm charge transfer'}</button>{pending&&<button disabled={busy||!!initial.error} onClick={()=>void checkStatus()}>Check saved transfer</button>}{pending&&!retirementInitial.error&&<div><label className="field">Cancellation reason<textarea value={retirementReason} disabled={busy||retirementSent} maxLength={500} onChange={e=>setRetirementReason(e.target.value)}/></label><p>Cancels this request only if no transfer has saved. Existing transfers are not reversed.</p><button disabled={busy||retirementReason.trim().length<4} onClick={()=>void retire()}>{retirementSent?'Retry cancellation':'Confirm cancellation of unsaved transfer'}</button></div>}{!pending&&<button disabled={busy} onClick={()=>setProposal(null)}>Edit transfer</button>}</>:<>
 <button disabled={busy||!!initial.error} onClick={()=>{setError('');setRevision(n=>n+1)}}>Refresh available charges</button>
 {review&&!review.sources.lines.some(line=>BigInt(line.routing_available_minor)>0n)?<p>No charges are currently available to transfer.</p>:review?<form onSubmit={e=>{e.preventDefault();prepare()}}><p>Billing account: {review.account_name}</p><label className="field">Charge<select required value={source} onChange={e=>setSource(e.target.value)}><option value="">Select a charge</option>{review.sources.lines.filter(line=>BigInt(line.routing_available_minor)>0n).map(line=><option key={line.source_key} value={line.source_key}>{line.description} · {billingDollars(line.routing_available_minor)} available</option>)}</select></label><label className="field">Amount USD<input required inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)}/></label><label className="field">Reason<textarea required minLength={4} maxLength={500} value={reason} onChange={e=>setReason(e.target.value)}/></label><button className="primary">Review transfer</button></form>:!error&&<p role="status">Loading available charges…</p>}
 </>}
 </section>;
}
